public sealed class CustomerSummaryResource : McpResource
{
    public override string Uri => "resource://customers/{customerId}";
    public override string Name => "Customer Summary";
    public override string Description => "Return a summary record for a customer by ID.";

    public async Task<McpResourceContent> GetAsync(
        string customerId,
        CancellationToken ct = default)
    {
        var customer = await _customers.GetByIdAsync(customerId, ct);
        if (customer is null)
            throw new McpResourceNotFoundException("Customer not found.");

        var json = JsonSerializer.Serialize(new
        {
            customer.Id,
            customer.Name,
            customer.Tier,
            customer.ActiveSince
        });

        return McpResourceContent.Text(json);
    }
}
